interface CoverageHolder extends LeadHolder {
  readonly pending: PendingSighting | null;
}

/**
 * Free coverage: whether a purchase of `type` would only buy what the player gets for free anyway. Only a type whose
 * sole eligible target is a carrier qualifies, by `planLead`, the eligibility rumor generation uses (sources, then
 * caches, then carriers), and then when either holds:
 * (a) the minute-28 reveal has happened: the free 30 s broadcast is fresher than a paid sighting of the older snapshot;
 * (b) the type is in the player's pending set after the gather phase: the next boundary delivers it free.
 */
function coveredFree(config: IntelConfig, world: WorldIndex, snapshots: readonly CarrierSnapshot[], holder: CoverageHolder, type: RubbingType): boolean {
  if (planLead(config, world, snapshots, holder, [type]).kind !== "carrier") return false;
  return world.tick >= config.carrierRevealTick || (holder.pending?.types.some((waiting) => waiting.type === type) ?? false);
}

/**
 * The one free-coverage predicate of the step (`covered` answers in phase 3) and of the UI
 * (`targetedRumorAvailability`), read from the state after its last step and the world view of that tick or a later one:
 * `covered` when a purchase of `type` by `playerId` would be free coverage (`coveredFree`), otherwise null.
 */
export function freeCoverage(config: IntelConfig, state: IntelState, view: IntelWorldView, playerId: string, type: RubbingType): "covered" | null {
  const world = readView(config, view, state.tick - 1);
  if (!state.started || !world.players.has(playerId) || !config.types.includes(type)) return null;
  const player = state.players.find((candidate) => candidate.id === playerId) ?? { id: playerId, journal: [], lastSightingBoundary: -1, pending: null };
  return coveredFree(config, world, state.snapshots, player, type) ? "covered" : null;
}

/**
 * What buying a targeted rumor for `type` would yield for `playerId` now, from the state after its last step and the
 * world view of that tick or a later one, without drawing: `covered` by `freeCoverage`, otherwise the lead it would
 * buy. A step on a later tick can differ only if it first crosses a snapshot boundary. A free trigger of the same
 * player and type in that step makes the purchase `covered` instead.
 */
export function targetedRumorAvailability(
  config: IntelConfig,
  state: IntelState,
  view: IntelWorldView,
  playerId: string,
  type: RubbingType,
): Exclude<TargetedRumorResult, "duplicate"> {
  const world = readView(config, view, state.tick - 1);
  if (!state.started || !world.players.has(playerId) || !config.types.includes(type)) return "none";
  if (freeCoverage(config, state, view, playerId, type) !== null) return "covered";
  const player = state.players.find((candidate) => candidate.id === playerId) ?? { id: playerId, journal: [], lastSightingBoundary: -1 };
  return targetedResult(planLead(config, world, state.snapshots, player, [type]));
}

function targetedResult(plan: LeadPlan): Exclude<TargetedRumorResult, "duplicate" | "covered"> {
  if (plan.kind === "journal") return "rumor";
  if (plan.kind === "none") return "none";
  if (plan.capped) return "capped";
  return plan.options.length > 0 ? "sighting" : "none";
}

