366	    ? channel.kind === "collect" && channel.sourceId === target.sourceId
367	    : channel.kind === "claim" && channel.cacheId === target.cacheId && channel.rubbingId === target.rubbingId);
368	
369	/**
370	 * One private match (§14): the only writer of its state. It runs the shared simulation on a 60 Hz fixed step,
371	 * applies validated client intent, and mirrors the simulation into the synced schema after every world step.
372	 *
373	 * The match flow (§2, §5): the match module (`stepMatch`) runs the lobby, the host's start, the ready countdown and
374	 * control start, then the end and the results; ships take input only between control start and the end. From control
375	 * start each world tick runs §5's order: the encounters (reservations first), the ledger's holds, the claim channel
376	 * (`stepClaim`), the flow (with the tick's accomplishments and the claim's end), then the reveals (`stepIntel`, whose
377	 * reveal messages go to exactly their recipients). A world tick that throws aborts the match (§12). Every system's
378	 * seed is derived from one private master secret per match (`deriveSeed`), never from the match code.
379	 *
380	 * Encounters (§6): each world step the room builds the tick's snapshot for `stepEncounters` (every ship, whether its
381	 * player is connected, pressed the grapple, or has a loaded arena) and applies the events: a landed grapple stops both
382	 * ships and opens a duel at sea, a `DuelMachine` (the standalone duel room's own) whose fight starts when the rules
383	 * say so; its end goes back as a report; the returns and respawns move ships. Reserved and respawning ships get
384	 * neutral input.
385	 *
386	 * Rubbings (§4, §11, §12): the objective ledger is the only writer of rubbings and gold; the room calls its operations
387	 * and never moves either itself. Holding E moored at an island's dock collects its first eligible source, or else
388	 * claims a rubbing from a recovery cache at that dock. A reservation reserves the duel in the ledger; the fight's end
389	 * is reported to it; the room reports `settled` to the encounter rules only when the ledger has settled the duel (the
390	 * winner's theft choice, or the default at the deadline), and only then do the players return. The world tick drives
391	 * every §12 timer: a drop disconnects the player in the ledger at once (the ship stays, and can be grappled), a
392	 * fighter away from an unfinished duel forfeits it after `duelAbsenceTicks`, the seat expires at the ledger's
393	 * deadline into a cache at the respawn dock, and any other leave is a quit into a cache at the nearest dock by sea.
394	 * No path removes a ship while the ledger still counts its player; `checkInvariants` checks that and `checkLedger`
395	 * after every tick.
396	 *
397	 * Fruit (§9): four pedestals at island docks, dealt from the fruit's own seed. A player moored at a pedestal's dock
398	 * inspects it (the kit goes to them only) and eats it by holding F for three seconds; the fruit rules alone decide who
399	 * eats, and each world tick hears this tick's reservations and disconnects. Every duel at sea starts with both
400	 * fighters' kits in its frame-0 state.
401	 *
402	 * Visibility (§16): every client has a Colyseus StateView. After each mirror the room puts into it the client's own
403	 * ship and every ship inside that ship's sight radius, and takes out the rest, so a ship out of sight is never encoded
404	 * into that client's patches. Ships in a duel or waiting to respawn are hidden from everyone else (a duel shows as a
405	 * marker). Grapples, markers and caches are filtered by the same sight rule (a grapple's target is blanked for a
406	 * viewer who cannot see it); a player's status (gold, rubbings, what their island and dock hold, their theft choice)
407	 * and duel go to that player only, and a duel's frames and probes are messages to its two fighters. A fighter or a
408	 * player waiting to respawn sees no other ship. Terrain is static content every client already has, so it is not
409	 * synced at all.
410	 */
411	export class MatchRoom extends Room<{ state: MatchStateSchema; metadata: MatchMetadata }> {
412	  override maxClients = privateMatch.maxPlayers;
413	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in InputGate. */
414	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
415	  override patchRate = PATCH_INTERVAL_MS;
416	  override state = new MatchStateSchema();
417	
418	  private readonly config = defaultSimulationConfig;
419	  private tuning: MatchTuning = DEFAULT_MATCH_TUNING;
420	  private encounterConfig: EncounterConfig = createEncounterConfig({ map: defaultSimulationConfig.map });
421	  private simulation: MatchState = createMatchState(0);
422	  private encounters: EncounterState = createEncounterState(this.encounterConfig);
423	  private ledger: LedgerState = createMatchLedger({ map: defaultSimulationConfig.map, seed: 0, rules: objectiveRules });
424	  /** §3's ruins, one per regular island, dealt from their own seed; they alone decide opens, answers and lockouts. */
425	  private ruins: RuinsState = createMatchRuins({ islands: [], seed: () => 0 }).ruins;
426	  /** Each player's recent ruin answers by request id: a retry gets the first verdict, never a second judgement. */
427	  private readonly ruinRequests = new RuinRequests<RuinResultMessage>();
428	  /** Ruin messages per session in the current second, for the rate cap. */
429	  private readonly ruinRate = new Map<string, { windowStart: number; count: number }>();
430	  /** §9's pedestals, one per regular island at its highest-id dock, and the fruit rules' state, dealt from their own seed. */
431	  private pedestals: readonly PedestalSite[] = [];
432	  private readonly fruitConfig: FruitConfig = createFruitConfig();
433	  private fruits: FruitState = { tick: 0, pedestals: [], channels: [], meals: [] };
434	  /** Fruit inspections per session in the current second, for the rate cap. */
435	  private readonly fruitRate = new Map<string, { windowStart: number; count: number }>();
436	  private readonly gates = new Map<string, InputGate>();
437	  /** Duels at sea by encounter id, from the grapple until their lobby leaves the fighters' views. */
438	  private readonly seaDuels = new Map<string, SeaDuel>();
439	  private nextDuelKey = 1;
440	  /** Players whose connection dropped and who have not come back or left. */
441	  private readonly away = new Map<string, Away>();
442	  /** Players who started a collection, a cache claim or a treasure claim this tick: their protection ends on the next (§6). */
443	  private protectionEndedNext = new Map<string, "claim" | "collection">();
444	  private readonly notices = new Map<string, Notices>();
445	  /** Ledger duels whose settlement is already in the players' notices. */
446	  private readonly noticed = new Set<string>();
447	  /** Theft choices per session in the current second, for the rate cap. */
448	  private readonly choiceRate = new Map<string, { windowStart: number; count: number }>();
449	  /** Reports the rules refused (none are expected), for tests. */
450	  private refusedReports = 0;
451	  /** Ledger requests the room made that the ledger refused, by operation and reason, for tests. */
452	  private readonly refusals: string[] = [];
453	  /** Invariant violations found after a world tick (none are expected), for tests. */
454	  private readonly violations: string[] = [];
455	  /** The creator's one-time token; cleared once the creator's seat is taken. */
456	  private createToken: string | undefined;
457	
458	  /** The match's private master secret (§3, §16): every system's seed is derived from it, never from the code. */
459	  private secret: Uint8Array = new Uint8Array(32);
460	  /** Duels at sea opened so far, for their derived seeds. */
461	  private duelsOpened = 0;
462	  /** The final island (§3, §5): its socket and its claim point, the treasure circle's centre. Never synced to everyone. */
463	  private finalIsland: { readonly socket: number; readonly claimPoint: ClaimPoint } = { socket: 0, claimPoint: { x: 0, y: 0 } };
464	  /** §2's match flow: the lobby, the ready countdown, control start, the timer, the end and the results. */
465	  private flowConfig: FlowConfig = matchConfigFor(DEFAULT_MATCH_TUNING);
466	  private flow: FlowState = createFlowState(this.flowConfig);
467	  /** Reports for the flow's next step: joins, leaves and start requests between ticks, accomplishments on a tick. */
468	  private flowReports: FlowReport[] = [];
469	  /** Reports dropped before the flow's step for naming a player it does not know (none are expected), for tests. */
470	  private readonly droppedReports: FlowReport[] = [];
471	  /** §5's claim channel, from control start. */
472	  private claimConfig: ClaimConfig | undefined;
473	  private claim: ClaimState | undefined;
474	  /** §2 and §5's reveals, from control start. */
475	  private intelConfig: IntelConfig | undefined;
476	  private intel: IntelState | undefined;
477	  /** Each player's route to the final island, once revealed to them. */
478	  private readonly routes = new Map<string, Route>();
479	  /** The (player, island) pairs already reported as visited, and each player's last reported gold. */
480	  private readonly visited = new Set<string>();
481	  private readonly reportedGold = new Map<string, number>();
482	  /** Start requests per session in the current second, for the rate cap. */
483	  private readonly startRate = new Map<string, { windowStart: number; count: number }>();
484	  /** Where each rubbing was at the last world tick, for the results' accomplishments. */
485	  private readonly lastLocations = new Map<string, RubbingLocation>();
486	  /** Test-only hooks (`testHooks`): a fault injected into the next world tick, and a world tick to pause after. */
487	  private faultNext = false;
488	  private pauseAt: number | undefined;
489	  private paused = false;
490	
491	  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
492	    return authorizeEntry(options);
493	  }
494	
495	  /** The match's timings; the server's test-only setting overrides it in a subclass (`startGameServer`). */
496	  protected matchTuning(): MatchTuning {
497	    return DEFAULT_MATCH_TUNING;
498	  }
499	
500	  override async onCreate(options: unknown): Promise<void> {
501	    // Only a token-carrying request creates a match. A join by code reaches here only when its match filled up or
502	    // closed after authorizeEntry admitted it (joinOrCreate then falls back to create).
503	    const parsed = createMatchOptionsSchema.safeParse(options);
504	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, MATCH_UNAVAILABLE_MESSAGE);
505	    this.createToken = parsed.data.createToken;
506	    const code = await this.allocateCode();
507	    this.tuning = this.matchTuning();
508	    this.encounterConfig = createEncounterConfig({ map: this.config.map, rules: this.tuning.encounters });
509	    this.encounters = createEncounterState(this.encounterConfig);
510	    // One private master secret per match; each system gets its own seed derived from it, never the match code (§3, §16).
511	    this.secret = this.tuning.masterSecret();
512	    this.simulation = createMatchState(this.seedOf("world"));
513	    this.ledger = createMatchLedger({ map: this.config.map, seed: this.seedOf("ledger"), rules: this.tuning.objectives, layout: this.tuning.sourceLayout });
514	    this.finalIsland = finalIslandOf(this.config.map, this.tuning.finalSocketSecret ?? this.seedOf("final-socket"));
515	    // Every source starts locked behind its island's ruin (§3); only a test opens islands from the start.
516	    const dealt = createMatchRuins({
517	      islands: ruinIslandsOf(this.ledger),
518	      seed: (attempt) => this.seedOf(attempt === 0 ? "ruins" : `ruins:${attempt}`),
519	      settings: this.tuning.testRuins,
520	    });
521	    this.ruins = dealt.ruins;
522	    this.ledger = openIslandsInLedger(this.ledger, dealt.openIslands);
523	    // §9's fruit, dealt onto the pedestals from the fruit's own seed (only a test pins the deal).
524	    this.pedestals = pedestalSites(this.config.map);
525	    this.fruits = createMatchFruits({ sites: this.pedestals, seed: this.seedOf("fruit"), layout: this.tuning.testFruits });
526	    for (const site of this.pedestals) {
527	      const marker = new PedestalMarkerSchema();
528	      marker.island = site.island;
529	      marker.dock = site.dock;
530	      marker.x = site.x;
531	      marker.y = site.y;
532	      this.state.pedestals.set(site.id, marker);
533	    }
534	    for (const island of Object.keys(this.ruins.ruins)) {
535	      const marker = new RuinMarkerSchema();
536	      const centre = islandCentre(this.config.map, Number(island));
537	      marker.island = Number(island);
538	      marker.x = centre.x;
539	      marker.y = centre.y;
540	      this.state.ruins.set(island, marker);
541	    }
542	    this.flowConfig = matchConfigFor(this.tuning);
543	    this.flow = createFlowState(this.flowConfig);
544	    this.state.code = code;
545	    this.state.protocolVersion = PROTOCOL_VERSION;
546	    this.state.custom = privateMatch.custom;
547	    this.state.minPlayers = this.flowConfig.minPlayers;
548	    this.state.durationTicks = this.flowConfig.durationTicks;
549	    this.state.readyTicks = this.flowConfig.readyTicks;
550	    this.state.treasureRadius = this.tuning.claim.circleRadiusTiles * this.config.map.subUnitsPerTile;
551	    this.state.finalSector = "";
552	    this.state.finalSectorIndex = -1;
553	    this.state.endReason = "";
554	    this.state.phase = this.flow.phase;
555	    // Colyseus copied the filterBy fields of the create request, the token among them, into the listing's metadata.
556	    // Replacing the metadata drops the token before the listing is first stored.
557	    await this.setMatchmaking({ metadata: { code, custom: privateMatch.custom, started: false } });
558	
559	    this.onMessage(MessageType.Input, (client, message: unknown) => {
560	      this.gates.get(client.sessionId)?.receive(message, this.simulation.frame);
561	    });
562	    // A duel's messages reach only its machine, and only from its two fighters.
563	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveInput(client.sessionId, message));
564	    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveProbeReply(client.sessionId, message));
565	    this.onMessage(DuelMessageType.Ready, (client, message: unknown) => {
566	      if (duelReadyMessageSchema.safeParse(message).success) this.duelOfSession(client.sessionId)?.machine.markReady(client.sessionId);
567	    });
568	    this.onMessage(RubbingMessageType.ChooseTheft, (client, message: unknown) => this.receiveTheftChoice(client.sessionId, message));
569	    this.onMessage(MatchMessageType.Start, (client, message: unknown) => this.receiveStart(client.sessionId, message));
570	    this.onMessage(RuinMessageType.Open, (client, message: unknown) => this.receiveOpenRuin(client.sessionId, message));
571	    this.onMessage(RuinMessageType.Answer, (client, message: unknown) => this.receiveAnswerRuin(client.sessionId, message));
572	    this.onMessage(FruitMessageType.Inspect, (client, message: unknown) => this.receiveInspectFruit(client.sessionId, message));
573	    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
574	    this.onMessage("*", () => undefined);
575	    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
576	  }
577	
578	  /**
579	   * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
580	   * carrying the creator's token, then only seats carrying this match's code. Throwing refuses and frees the seat.
581	   */
582	  override onJoin(client: Client, options: unknown): void {
583	    this.admit(options);
584	    // §2: a match that has left its lobby takes no one new, whatever path the request took.
585	    if (this.flow.phase !== "lobby") throw new ServerError(JoinRefusal.MatchFull, MATCH_STARTED_MESSAGE);
586	    this.flowReports.push({ kind: "join", playerId: client.sessionId });
587	    this.simulation = addShip(this.config, this.simulation, client.sessionId);
588	    this.ledgerStep("addPlayer", addPlayer(this.ledger, { playerId: client.sessionId, tick: this.simulation.worldTick }));
589	    this.gates.set(client.sessionId, new InputGate());
590	    client.view = new StateView();
591	    this.mirror();
592	  }
593	
594	  /**
595	   * A player's connection dropped without leaving (§12). The ledger marks them disconnected at once (their hold is
596	   * cancelled and their seat reserved until its deadline); the ship stays in the world and can be grappled. A fighter
597	   * in an unfinished duel is marked away, the fight going on with their input substituted, and forfeits if still away
598	   * after `duelAbsenceTicks`. Colyseus keeps the socket's seat for the outer bound only.
599	   */
600	  override onDrop(client: Client): void {
601	    const id = client.sessionId;
602	    // A request refused in onJoin (a wrong code, a used token) still drops and leaves, but never became a player.
603	    if (findPlayer(this.ledger, id) === undefined) return;
604	    const tick = this.simulation.worldTick;
605	    this.ledgerStep("disconnectPlayer", disconnectPlayer(this.ledger, { playerId: id, tick }));
606	    const duel = this.duelOfSession(id);
607	    const fighting = duel !== undefined && duel.machine.outcome === undefined;
608	    if (fighting) duel.machine.drop(id);
609	    const reconnection = this.allowReconnection(client, this.tuning.reconnectionSeconds);
610	    reconnection.catch(() => undefined);
611	    this.away.set(id, { reconnection, duelAbsentSince: fighting ? tick : undefined });
612	  }
613	
614	  /** The same player is back before the deadline: the same identity, view, ship and rubbings; a fighter resumes. */
615	  override onReconnect(client: Client): void {
616	    const id = client.sessionId;
617	    this.away.delete(id);
618	    this.ledgerStep("reconnectPlayer", reconnectPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick }));
619	    this.duelOfSession(id)?.machine.reconnect(id);
620	  }
621	
622	  /**
623	   * A player is gone for good. Unless the reservation already expired (the world tick removed them), this is a quit:
624	   * a consented leave, or Colyseus' outer bound closing first. The ledger forfeits a duel in progress and sends the
625	   * rest of their rubbings into a cache at the dock nearest their ship by sea; then the ship leaves.
626	   */
627	  override onLeave(client: Client): void {
628	    const id = client.sessionId;
629	    const player = findPlayer(this.ledger, id);
630	    if (player !== undefined && player.status !== "left") {
631	      this.quit(id);
632	      this.flowReports.push({ kind: "leave", playerId: id });
633	    }
634	    this.removePlayer(id);
635	    client.view?.dispose();
636	    client.view = undefined;
637	    this.mirror();
638	  }
639	
640	  /**
641	   * Test-only (the server's test-placement setting, off by default): puts a player's ship at rest on a navigable tile.
642	   * Visibility follows at once, as after any move.
643	   */
644	  placeShip(sessionId: string, placement: Placement): void {
645	    this.simulation = placeShip(this.config, this.simulation, sessionId, placement);
646	    this.mirror();
647	  }
