649	  /** The ship ids a client's view holds, for tests and diagnostics. */
650	  viewedShipIds(sessionId: string): string[] {
651	    const view = this.clients.get(sessionId)?.view;
652	    if (view === undefined) return [];
653	    return [...this.state.ships.values()].filter((ship) => view.has(ship)).map((ship) => ship.id);
654	  }
655	
656	  /** Inputs dropped per client and reason, for tests and diagnostics. */
657	  droppedInputs(sessionId: string): InputGate["dropped"] | undefined {
658	    return this.gates.get(sessionId)?.dropped;
659	  }
660	
661	  /** The encounter rules' state, for tests. */
662	  get encounterState(): EncounterState {
663	    return this.encounters;
664	  }
665	
666	  /** The simulation state, for tests. */
667	  get matchState(): MatchState {
668	    return this.simulation;
669	  }
670	
671	  /** The objective ledger, for tests. */
672	  get ledgerState(): LedgerState {
673	    return this.ledger;
674	  }
675	
676	  /** The match's timings, for tests. */
677	  get timings(): MatchTuning {
678	    return this.tuning;
679	  }
680	
681	  /** Reports the encounter rules refused, for tests (none are expected). */
682	  get refusedDuelReports(): number {
683	    return this.refusedReports;
684	  }
685	
