1068	          notice.channelResultAt = tick;
1069	        }
1070	        continue;
1071	      }
1072	      const started =
1073	        target.kind === "collect"
1074	          ? this.ledgerStep("startCollect", startCollect(this.ledger, { playerId: id, sourceId: target.sourceId, tick }))
1075	          : this.ledgerStep("startCacheClaim", startCacheClaim(this.ledger, { playerId: id, cacheId: target.cacheId, rubbingId: target.rubbingId, tick }));
1076	      if (started.ok && !this.protectionEndedNext.has(id)) this.protectionEndedNext.set(id, "collection");
1077	    }
1078	  }
1079	
1080	  /**
1081	   * §9's eating, one world tick, after the encounters (so a reservation accepted on this tick interrupts it) and before
1082	   * the ledger's holds and the claim: every player in the match, at the pedestal of the dock their ship is moored at
1083	   * (unless waiting out of the world to respawn), holding F, reserved for a duel, disconnected (a drop cancels the
1084	   * channel, §12). The fruit rules alone decide who eats; each player's last result goes to their notices.
1085	   */
1086	  private stepFruits(frame: number, tick: number): void {
1087	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1088	    const waiting = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
1089	    const players: FruitPlayer[] = [];
1090	    for (const player of this.ledger.players) {
1091	      if (player.status === "left") continue;
1092	      const id = player.id;
1093	      // Every player in the ledger's match has a ship and an input gate (the room's invariant).
1094	      const ship = ships.get(id)!;
1095	      const gate = this.gates.get(id)!;
1096	      players.push({
1097	        playerId: id,
1098	        pedestalId: waiting.has(id) ? null : (pedestalAtDock(this.pedestals, ship.dock)?.id ?? null),
1099	        // A lapsed input is neutral (§12), so a stalled client holds nothing.
1100	        holding: (gate.inputAt(frame).buttons & FRUIT_BUTTON) !== 0,
1101	        reserved: duelOf(this.encounters, id) !== undefined,
1102	        disconnected: player.status === "disconnected",
1103	        left: false,
1104	      });
1105	    }
1106	    const stepped = stepFruits(this.fruitConfig, this.fruits, { tick, players });
1107	    this.fruits = stepped.state;
1108	    for (const result of stepped.results) this.noteFruitResult(result);
1109	  }
1110	
1111	  /** A fruit result in its player's notices, for their panel: what ended their last attempt, or the meal. */
1112	  private noteFruitResult(result: FruitResult): void {
1113	    // Only a tick not later than the state's is rejected, and the room steps every world tick once.
1114	    if (result.kind === "tick-rejected") return;
1115	    // F still held at the pedestal the player has just emptied: the meal stays their last result, not a refusal.
1116	    if (result.kind === "eat-refused" && this.fruits.meals.some((meal) => meal.playerId === result.playerId && meal.pedestalId === result.pedestalId)) return;
1117	    const notice = this.noticesOf(result.playerId);
1118	    notice.fruitResultAt = result.tick;
1119	    if (result.kind === "eat-started") notice.fruitResult = "";
1120	    else if (result.kind === "eat-completed") notice.fruitResult = `eaten:${result.kit}`;
1121	    else notice.fruitResult = `${result.kind === "eat-refused" ? "refused" : "interrupted"}:${result.reason}`;
1122	  }
1123	
1124	  /**
1125	   * §5's claim channel, one world tick, after the encounters (so a reservation accepted on this tick resets a channel
1126	   * first) and the ledger's holds: every ship whose player is in the match, whether it holds every type (the ledger),
1127	   * holds E, is connected and protected, and every duel the encounter rules hold reserved. Returns the claim's
1128	   * `match-ended`, for the flow's step on the same tick.
1129	   */
1130	  private stepClaim(frame: number, tick: number): FlowReport | undefined {
1131	    if (this.claimConfig === undefined || this.claim === undefined) return undefined;
1132	    const held = this.heldPlayers();
1133	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
1134	    const players: ClaimPlayer[] = [];
1135	    for (const ship of this.simulation.ships) {
1136	      const player = findPlayer(this.ledger, ship.id);
1137	      if (player === undefined || player.status === "left") continue;
1138	      const gate = this.gates.get(ship.id);
1139	      players.push({
1140	        id: ship.id,
1141	        x: ship.x,
1142	        y: ship.y,
1143	        speed: ship.speed,
1144	        holdsAllTypes: holdsAllTypes(this.ledger, ship.id),
1145	        interact: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & INTERACT_BUTTON) !== 0,
1146	        connected: player.status === "connected" && this.clients.get(ship.id) !== undefined,
1147	        protected: (records.get(ship.id)?.protection ?? null) !== null,
1148	      });
1149	    }
1150	    const encounters = this.encounters.duels.map((duel) => ({ id: duel.id, playerIds: duel.players }));
1151	    const stepped = stepClaim(this.claimConfig, this.claim, { tick, players, encounters });
1152	    this.claim = stepped.state;
1153	    let end: FlowReport | undefined;
1154	    for (const event of stepped.events) end = this.applyClaimEvent(event) ?? end;
1155	    return end;
1156	  }
1157	
1158	  private applyClaimEvent(event: ClaimEvent): FlowReport | undefined {
1159	    switch (event.kind) {
1160	      case "claim-interrupted": {
1161	        const notice = this.noticesOf(event.playerId);
1162	        notice.claimInterrupt = event.reason;
1163	        notice.claimInterruptAt = event.tick;
1164	        return undefined;
1165	      }
1166	      case "claim-started":
1167	        this.noticesOf(event.playerId).claimInterrupt = "";
1168	        return undefined;
1169	      case "protection-ended":
1170	        // §6: claiming ends protection; the encounter rules hear it on the next tick.
1171	        this.protectionEndedNext.set(event.playerId, "claim");
1172	        return undefined;
1173	      case "match-ended":
1174	        return { kind: "match-ended", tick: event.tick, reason: event.reason, winner: event.winner };
1175	      default:
1176	        // `claim-completed` shows in the results; `duel-ended-without-theft` is applied when the match ends.
1177	        return undefined;
1178	    }
1179	  }
