1761	   * position), and the results once the match has ended.
1762	   */
1763	  private mirrorFlow(): void {
1764	    const flow = this.flow;
1765	    this.state.phase = flow.phase;
1766	    this.state.hostSeat = flow.host === null ? 0 : this.seatOf(flow.host);
1767	    this.state.readyEndsAt = flow.readyTick === null ? 0 : flow.readyTick + this.flowConfig.readyTicks;
1768	    this.state.controlStartTick = flow.controlStartTick ?? 0;
1769	    this.state.deadlineTick = this.claimConfig?.deadlineTick ?? 0;
1770	    this.state.remainingTicks = remaining(flow, flow.tick);
1771	    const present = new Set<string>();
1772	    for (const player of flow.players) {
1773	      if (player.left) continue;
1774	      const key = String(player.order + 1);
1775	      present.add(key);
1776	      if (!this.state.roster.has(key)) {
1777	        const entry = new RosterEntrySchema();
1778	        entry.seat = player.order + 1;
1779	        this.state.roster.set(key, entry);
1780	      }
1781	    }
1782	    for (const id of [...this.state.roster.keys()]) if (!present.has(id)) this.state.roster.delete(id);
1783	    const results = flow.results;
1784	    if (results !== null && this.state.endReason === "") {
1785	      this.state.endReason = results.reason;
1786	      this.state.winnerSeat = results.winner === null ? 0 : this.seatOf(results.winner);
1787	      this.state.endTick = results.tick;
1788	      this.state.elapsedTicks = results.elapsedTicks;
1789	      for (const line of results.players) {
1790	        const synced = new ResultLineSchema();
1791	        synced.seat = this.seatOf(line.id);
1792	        synced.winner = line.winner;
1793	        synced.left = line.left;
1794	        synced.rubbingsHeld = line.rubbingsHeld;
1795	        synced.collected = line.collected;
1796	        synced.thefts = line.thefts;
1797	        synced.lost = line.lost;
1798	        synced.duelsWon = line.duelsWon;
1799	        synced.duelsLost = line.duelsLost;
1800	        synced.duelsDrawn = line.duelsDrawn;
1801	        synced.gold = line.gold;
1802	        synced.cachesClaimed = line.cachesClaimed;
1803	        synced.islandsVisited = line.islandsVisited;
1804	        this.state.results.push(synced);
1805	      }
1806	    }
1807	  }
