1809	  /** The rules' telegraphs and each player's status into the synced state (markers change only on events). */
1810	  private mirrorEncounters(present: ReadonlySet<string>): void {
1811	    const keys = new Set<string>();
1812	    for (const attempt of this.encounters.attempts) {
1813	      for (const [key, defenderId] of [
1814	        [attempt.attackerId, attempt.defenderId],
1815	        [attempt.attackerId + BLANK_GRAPPLE_SUFFIX, ""],
1816	      ] as const) {
1817	        keys.add(key);
1818	        let synced = this.state.grapples.get(key);
1819	        if (synced === undefined) {
1820	          synced = new GrappleSchema();
1821	          synced.attackerId = attempt.attackerId;
1822	          this.state.grapples.set(key, synced);
1823	        }
1824	        synced.defenderId = defenderId;
1825	        synced.aim = attempt.aim;
1826	        synced.startTick = attempt.startTick;
1827	        synced.landTick = attempt.landTick;
1828	      }
1829	    }
1830	    for (const key of [...this.state.grapples.keys()]) if (!keys.has(key)) this.state.grapples.delete(key);
1831	
1832	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
1833	    for (const id of present) {
1834	      let status = this.state.status.get(id);
1835	      if (status === undefined) {
1836	        status = new PlayerStatusSchema();
1837	        this.state.status.set(id, status);
1838	      }
1839	      const record = records.get(id);
1840	      status.mode = record?.respawn != null ? "respawning" : duelOf(this.encounters, id) !== undefined ? "duel" : "sea";
1841	      status.protection = record?.protection?.source ?? "";
1842	      status.protectedUntil = record?.protection?.endTick ?? 0;
1843	      status.cooldownUntil = record?.cooldownEndTick ?? 0;
1844	      status.respawnAt = record?.respawn?.respawnTick ?? 0;
1845	    }
1846	    for (const id of [...this.state.status.keys()]) if (!present.has(id)) this.state.status.delete(id);
1847	  }
