1849	  /**
1850	   * The ledger into the synced state: each player's private status (gold, rubbings, what their island and dock hold
1851	   * while moored there, E's target and progress, their theft choice and their last results), and a contentless marker
1852	   * for each recovery cache.
1853	   */
1854	  private mirrorObjectives(present: ReadonlySet<string>): void {
1855	    const map = this.config.map;
1856	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1857	    const held = this.heldPlayers();
1858	    for (const id of present) {
1859	      const status = this.state.status.get(id)!;
1860	      const player = findPlayer(this.ledger, id);
1861	      const ship = ships.get(id)!;
1862	      const moored = ship.dock !== NOT_DOCKED && !held.has(id) && player !== undefined;
1863	      status.gold = player?.gold ?? 0;
1864	      status.rubbings = player === undefined ? "" : heldTypes(this.ledger, id).join(",");
1865	      status.islandTypes = moored ? sealedTypesAt(this.ledger, map.docks[ship.dock]!.island).join(",") : "";
1866	      status.cacheTypes = moored ? cachedTypesAt(this.ledger, map, ship.dock).join(",") : "";
1867	      const target = moored && player.status === "connected" ? interactTarget(this.ledger, map, id, ship.dock) : undefined;
1868	      status.target = target === undefined ? "" : `${target.kind}:${target.type}`;
1869	      const channel = player?.channel ?? null;
1870	      status.channel = channel?.kind ?? "";
1871	      status.channelType = channel === null ? "" : (this.ledger.rubbings.find((rubbing) => rubbing.id === channel.rubbingId)?.type ?? "");
1872	      status.channelHeld = channel?.heldTicks ?? 0;
1873	      status.channelTotal = channel === null ? 0 : channel.kind === "collect" ? this.ledger.rules.collectTicks : this.ledger.rules.cacheClaimTicks;
1874	      const choosing = this.ledger.duels.find((duel) => duel.phase === "choosing" && duel.result?.winner === id);
1875	      const options = choosing === undefined ? [] : eligibleTheftTypes(this.ledger, choosing.id);
1876	      status.theftDuel = choosing === undefined || options.length === 0 ? "" : (this.seaDuels.get(choosing.id)?.key ?? "");
1877	      status.theftOptions = status.theftDuel === "" ? "" : options.join(",");
1878	      status.theftDeadline = status.theftDuel === "" ? 0 : choosing!.choiceDeadline!;
1879	      const notice = this.noticesOf(id);
1880	      status.channelResult = notice.channelResult;
1881	      status.channelResultAt = notice.channelResultAt;
1882	      status.settledRole = notice.settledRole;
1883	      status.stolen = notice.stolen;
1884	      status.goldChange = notice.goldChange;
1885	      status.settledAt = notice.settledAt;
1886	      status.settledChoice = notice.settledChoice;
1887	      status.choiceDeadline = notice.choiceDeadline;
1888	      this.mirrorClaim(id, status, ship, player === undefined ? false : holdsAllTypes(this.ledger, id), notice);
1889	      this.mirrorRuin(id, status, moored ? islandOfDock(map, ship.dock) : null);
1890	      this.mirrorFruit(id, status, moored ? pedestalAtDock(this.pedestals, ship.dock) : undefined, notice);
1891	    }
1892	    for (const marker of this.state.ruins.values()) marker.unlocked = islandUnlocked(this.ledger, marker.island);
1893	    for (const pedestal of this.fruits.pedestals) this.state.pedestals.get(pedestal.id)!.full = pedestal.eatenBy === null;
1894	    const caches = new Set<string>();
1895	    for (const cache of this.ledger.caches) {
1896	      if (cacheRubbings(this.ledger, cache.id).length === 0) continue;
1897	      caches.add(cache.id);
1898	      let synced = this.state.caches.get(cache.id);
1899	      if (synced === undefined) {
1900	        synced = new CacheMarkerSchema();
1901	        synced.x = cache.x;
1902	        synced.y = cache.y;
1903	        synced.dock = cacheDock(map, cache);
1904	        this.state.caches.set(cache.id, synced);
1905	      }
1906	    }
1907	    for (const id of [...this.state.caches.keys()]) if (!caches.has(id)) this.state.caches.delete(id);
1908	  }
1909	
1910	  /**
1911	   * §9 in a player's own status only: their kit, whether the pedestal where they are moored is full, their eating
1912	   * progress and how their last attempt ended.
1913	   */
1914	  private mirrorFruit(id: string, status: PlayerStatusSchema, site: PedestalSite | undefined, notice: Notices): void {
1915	    status.kit = kitOf(this.fruits, id);
1916	    status.pedestal = site === undefined ? "" : this.fruits.pedestals.find((pedestal) => pedestal.id === site.id)!.eatenBy === null ? "full" : "empty";
1917	    status.fruitHeld = this.fruits.channels.find((channel) => channel.playerId === id)?.held ?? 0;
1918	    status.fruitTotal = this.fruitConfig.eatTicks;
1919	    status.fruitResult = notice.fruitResult;
1920	    status.fruitResultAt = notice.fruitResultAt;
1921	  }
1922	
1923	  /** §3: the ruin of the island a player is moored at, in their own status only: its state, their session and lockout. */
1924	  private mirrorRuin(id: string, status: PlayerStatusSchema, island: number | null): void {
1925	    const ruin = island === null ? undefined : findRuin(this.ruins, island);
1926	    status.ruin = ruin === undefined ? "" : hasSolved(ruin, id) ? "solved" : islandUnlocked(this.ledger, ruin.island) ? "unlocked" : "locked";
1927	    status.ruinOpen = ruin !== undefined && sessionOf(ruin, id) !== undefined;
1928	    status.ruinLockedUntil = ruin === undefined ? 0 : lockedUntil(ruin, id);
1929	  }
1930	
1931	  /**
1932	   * A player's own view of the final island (§5, §16): their route once the reveals gave it (inactive while their set
1933	   * is broken), whether they hold every type, and their claim: channelling (with the ticks held and needed), waiting
1934	   * for another claimer to finish, and why their last channel reset.
1935	   */
1936	  private mirrorClaim(id: string, status: PlayerStatusSchema, ship: { x: number; y: number }, fullSet: boolean, notice: Notices): void {
1937	    const route = this.routes.get(id);
1938	    status.seat = this.seatOf(id);
1939	    status.fullSet = fullSet;
1940	    status.routeKnown = route !== undefined;
1941	    status.routeActive = route?.active === true;
1942	    status.routeX = route?.x ?? 0;
1943	    status.routeY = route?.y ?? 0;
1944	    const channel = this.claim?.channel ?? null;
1945	    const config = this.claimConfig;
1946	    const inCircle = route !== undefined && config !== undefined && insideTreasureCircle(config, ship.x, ship.y);
1947	    status.claim = channel?.playerId === id ? "channel" : channel !== null && fullSet && inCircle ? "waiting" : "";
1948	    status.claimHeld = channel?.playerId === id ? channel.progress : 0;
1949	    status.claimTotal = config?.channelTicks ?? this.tuning.claim.channelTicks;
1950	    status.claimInterrupt = notice.claimInterrupt;
1951	    status.claimInterruptAt = notice.claimInterruptAt;
1952	  }
1953	
1954	  /**
1955	   * Each client's view (§3, §6, §12, §16): its own ship unless it waits to respawn, the ships it can see that are not
1956	   * in a duel or waiting to respawn, the grapples whose attacker it sees or that aim at it (with the target blanked
1957	   * unless it sees the target too), the duel markers and caches in its sight, its own status and its own duel. A
1958	   * fighter or a player waiting to respawn sees no other ship, grapple, marker or cache. Nothing else is encoded for it.
1959	   */
1960	  private updateViews(): void {
1961	    const inDuel = new Set(this.encounters.duels.flatMap((duel) => duel.players));
1962	    const respawning = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
1963	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1964	    for (const client of this.clients) {
1965	      const view = client.view;
1966	      if (view === undefined) continue;
1967	      const self = client.sessionId;
1968	      const viewer = ships.get(self);
1969	      const away = inDuel.has(self) || respawning.has(self);
1970	      const sync = (item: Parameters<typeof view.add>[0], visible: boolean) => {
1971	        const shown = view.has(item);
1972	        if (visible && !shown) view.add(item);
1973	        else if (!visible && shown) view.remove(item);
1974	      };
1975	      const visible = visibleShipIds(this.config, this.simulation, self);
1976	      for (const [id, ship] of this.state.ships) {
1977	        sync(ship, id === self ? !respawning.has(id) : visible.has(id) && !away && !inDuel.has(id) && !respawning.has(id));
1978	      }
1979	      const sees = (id: string) => {
1980	        const other = ships.get(id);
1981	        return !away && viewer !== undefined && other !== undefined && canSee(this.config, viewer, other);
1982	      };
1983	      for (const attempt of this.encounters.attempts) {
1984	        const aimedAt = attempt.attackerId === self || attempt.defenderId === self;
1985	        const full = aimedAt || (sees(attempt.attackerId) && sees(attempt.defenderId));
1986	        const blank = !full && sees(attempt.attackerId);
1987	        const fullEntry = this.state.grapples.get(attempt.attackerId);
1988	        const blankEntry = this.state.grapples.get(attempt.attackerId + BLANK_GRAPPLE_SUFFIX);
1989	        if (fullEntry !== undefined) sync(fullEntry, full);
1990	        if (blankEntry !== undefined) sync(blankEntry, blank);
1991	      }
1992	      for (const marker of this.state.markers.values()) sync(marker, !away && viewer !== undefined && pointInSight(this.config, viewer, marker));
1993	      for (const cache of this.state.caches.values()) sync(cache, !away && viewer !== undefined && pointInSight(this.config, viewer, cache));
1994	      // A pedestal: whether it is full, for players in sight of its dock (§9, §16); never which fruit.
1995	      for (const pedestal of this.state.pedestals.values()) sync(pedestal, !away && viewer !== undefined && pointInSight(this.config, viewer, pedestal));
1996	      // An island's ruin: whether it is unlocked, for players in sight of the island (a ship moored there always is, §16).
1997	      for (const ruin of this.state.ruins.values()) {
1998	        sync(ruin, !away && viewer !== undefined && pointInSight(this.config, viewer, nearestIslandPoint(this.config.map, ruin.island, viewer.x, viewer.y)));
1999	      }
2000	      for (const [id, status] of this.state.status) sync(status, id === self);
2001	      for (const lobby of this.state.duels.values()) sync(lobby, lobby.seats.some((seat) => seat.sessionId === self));
2002	    }
2003	  }
2004	
2005	  private async allocateCode(): Promise<string> {
2006	    for (let attempt = 0; attempt < 16; attempt++) {
2007	      const code = generateMatchCode();
2008	      const taken = await matchMaker.query({ name: this.roomName, code });
2009	      if (taken.length === 0) return code;
2010	    }
2011	    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a match code");
2012	  }
2013	}
