    renderRuinHud(matchSection, {
      status: ruin,
      verdict: ruins.lastVerdict,
      sighted: sightedRuinsLine([...(state.ruins?.values() ?? [])], islandName),
    });
    const fruitStatus: FruitStatus | undefined =
      encounter === undefined
        ? undefined
        : {
            kit: encounter.kit,
            pedestal: encounter.pedestal,
            fruitHeld: encounter.fruitHeld,
            fruitTotal: encounter.fruitTotal,
            fruitResult: encounter.fruitResult,
            fruitResultAt: encounter.fruitResultAt,
          };
