import { fileURLToPath } from "node:url";
import { defineConfig, devices } from "@playwright/test";

const root = fileURLToPath(new URL("../..", import.meta.url));
const SERVER_PORT = 2593;
const WEB_PORT = 5393;

/**
 * Browser scenarios against the real server and web client on their fixed ports. Both start from source: the server
 * through tsx (its dev and test entry, with test placement on), the client as a fresh Vite production build served by
 * `vite preview`, so no prior build is needed.
 */
export default defineConfig({
  testDir: ".",
  testMatch: "**/*.spec.ts",
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: false,
  workers: 1,
  retries: 0,
  forbidOnly: !!process.env["CI"],
  reporter: "list",
  use: {
    baseURL: `http://localhost:${WEB_PORT}`,
    trace: "retain-on-failure",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: [
    {
      command: "npm run start:source -w @pirate-sea-race/server",
      cwd: root,
      // The dev and test entry reads the test-only settings: the scenarios put ships where they need them, every match
      // deals its rubbings in a fixed layout (Suns on Palm Key and Old Stones, Moons on Ember Rock and Mist Cay), its
      // final island is the one the pinned secret picks (`FINAL_SECRET` in helpers.ts), and it runs short: a 3 s ready
      // countdown, 1 s of departure protection and a 10-minute match. Every island is open from the start (test-only
      // ruins), so the scenarios about the loop (`theft-loop`, `full-match`) collect without solving ruins; `ruin-solve`
      // gives its match locked ruins of a pinned kind through the next-match route (`nextMatchRuins` in helpers.ts). The
      // fruit deal is pinned too (Ember on Palm Key and Mist Cay, Smoke on Ember Rock and Old Stones), so `fruit-duel`
      // knows which pedestal holds Ember; players who never eat stay the Duelist.
      env: {
        PORT: String(SERVER_PORT),
        PIRATE_SEA_RACE_TEST_PLACEMENT: "1",
        PIRATE_SEA_RACE_TEST_SOURCES: "sun,sun|moon,moon|sun,sun|moon,moon",
        PIRATE_SEA_RACE_TEST_TIMINGS: "ready=60,protection=20,match=12000",
        PIRATE_SEA_RACE_TEST_FINAL_SECRET: "3",
        PIRATE_SEA_RACE_TEST_RUINS: "*=open",
        PIRATE_SEA_RACE_TEST_FRUITS: "ember,smoke,smoke,ember",
      },
      url: `http://localhost:${SERVER_PORT}/__healthcheck`,
      reuseExistingServer: false,
      timeout: 60_000,
    },
    {
      command: "npm run build -w @pirate-sea-race/web && npm run preview -w @pirate-sea-race/web",
      cwd: root,
      url: `http://localhost:${WEB_PORT}`,
      reuseExistingServer: false,
      timeout: 120_000,
    },
  ],
});
import { expect, type APIRequestContext, type Browser, type BrowserContext, type Page, type TestInfo } from "@playwright/test";
import { HEADING_COUNT, isNavigable, seaMap, shipTuning, SUB_UNITS_PER_TILE, TILE_PIXELS, WORLD_STEPS_PER_SECOND } from "../../packages/content/src/index.js";
import { TEST_NEXT_MATCH_RUINS_PATH, TEST_NEXT_MATCH_TIMINGS_PATH, TEST_PLACEMENT_PATH, type TestRuins, type TestTimings } from "../../packages/protocol/src/index.js";

export const SERVER_URL = "http://localhost:2593";
export const TILE = SUB_UNITS_PER_TILE;
const PIXELS_PER_SUB_UNIT = TILE_PIXELS / SUB_UNITS_PER_TILE;

export interface Readout {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly heading: number;
  readonly speed: number;
  readonly dock: number;
}

export interface DrawnShip {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly color: string;
}

export async function createMatch(page: Page): Promise<string> {
  await page.goto("/");
  await page.getByRole("button", { name: "Create match" }).click();
  await expect(page.getByTestId("hud-status")).toHaveText("connected");
  const code = page.getByTestId("hud-code");
  await expect(code).toHaveText(/^[A-Z0-9]{6}$/);
  return (await code.textContent())!;
}

export async function joinMatch(page: Page, code: string): Promise<void> {
  await page.goto("/");
  await page.getByLabel("Match code").fill(code);
  await page.getByRole("button", { name: "Join", exact: true }).click();
  await expect(page.getByTestId("hud-status")).toHaveText("connected");
}

/**
 * The pinned final-socket secret of the browser server (`PIRATE_SEA_RACE_TEST_FINAL_SECRET` in the Playwright config),
 * so a scenario knows where the final island is.
 */
export const FINAL_SECRET = 3;

/**
 * Starts a match through its lobby, as players do (§2): the host clicks Start, every page shows the ready countdown,
 * then the running timer once control starts; the departure's short protection (test-only, 1 s) runs out.
 */
export async function startMatch(host: Page, ...others: Page[]): Promise<void> {
  const start = host.getByRole("button", { name: "Start match" });
  await expect(start).toBeEnabled();
  await start.click();
  for (const page of [host, ...others]) {
    await expect(page.getByTestId("match-timer")).toHaveAttribute("data-state", "running", { timeout: 15_000 });
    await expect(page.getByTestId("lobby")).toBeHidden();
  }
  for (const page of [host, ...others]) await expect(page.getByTestId("hud-protection")).toHaveAttribute("data-state", "none", { timeout: 5000 });
}

/**
 * A lone player's match needs a second player to start (§2: private matches start with two). A companion joins from
 * its own browser context and stays at its spawn slot; the host starts. Close the returned context when done.
 */
export async function startWithCompanion(browser: Browser, host: Page, code: string): Promise<BrowserContext> {
  const context = await browser.newContext();
  const companion = await context.newPage();
  await joinMatch(companion, code);
  await expect(host.getByTestId("hud-players")).toHaveText("2");
  await startMatch(host, companion);
  return context;
}

export async function selfId(page: Page): Promise<string> {
  return (await page.getByTestId("hud-self").textContent())!;
}

/** Every ship the page's HUD lists, with the latest decoded server state. */
export async function listed(page: Page): Promise<Readout[]> {
  return page.evaluate(() =>
    [...document.querySelectorAll<HTMLElement>('[data-testid="positions"] [data-ship-id]')].map((item) => ({
      id: item.dataset["shipId"]!,
      slot: Number(item.dataset["slot"]),
      x: Number(item.dataset["x"]),
      y: Number(item.dataset["y"]),
      heading: Number(item.dataset["heading"]),
      speed: Number(item.dataset["speed"]),
      dock: Number(item.dataset["dock"]),
    })),
  );
}

export async function listedIds(page: Page): Promise<string[]> {
  return (await listed(page)).map((ship) => ship.id).sort();
}

/** A ship's authoritative state in a page's HUD, or undefined when the page does not list it. */
export async function readout(page: Page, shipId: string): Promise<Readout | undefined> {
  return (await listed(page)).find((ship) => ship.id === shipId);
}

export async function drawnShips(page: Page): Promise<DrawnShip[]> {
  return JSON.parse((await page.getByTestId("game").getAttribute("data-drawn-ships")) ?? "[]") as DrawnShip[];
}

export async function drawnIds(page: Page): Promise<string[]> {
  return (await drawnShips(page)).map((ship) => ship.id).sort();
}

/**
 * Test-only placement (the server's PIRATE_SEA_RACE_TEST_PLACEMENT setting, on for these tests): puts a player's
 * ship at rest on a tile, then waits until the page shows it there.
 */
export async function place(request: APIRequestContext, page: Page, code: string, tileX: number, tileY: number, heading: number): Promise<void> {
  const sessionId = await selfId(page);
  const response = await request.post(`${SERVER_URL}${TEST_PLACEMENT_PATH}`, { data: { code, sessionId, tileX, tileY, heading } });
  expect(response.status(), await response.text()).toBe(200);
  await expect
    .poll(async () => {
      const ship = await readout(page, sessionId);
      return ship === undefined ? undefined : [ship.x, ship.y, ship.speed];
    })
    .toEqual([tileX * TILE + TILE / 2, tileY * TILE + TILE / 2, 0]);
}

/**
 * Test-only (with the test placement setting, as here): the next match created runs with these timings, in world
 * ticks, on top of the browser server's own; later matches keep the server's.
 */
export async function nextMatchTimings(request: APIRequestContext, timings: TestTimings): Promise<void> {
  const response = await request.post(`${SERVER_URL}${TEST_NEXT_MATCH_TIMINGS_PATH}`, { data: timings });
  expect(response.status(), await response.text()).toBe(200);
}

/**
 * Test-only (with the test placement setting, as here): the next match created deals its ruins with these settings
 * instead of the browser server's (which opens every island), for example `{ "0": "sequence" }`: Palm Key's ruin
 * locked, and a sequence. Islands not named are locked, of whatever kind the ruins' seed deals.
 */
export async function nextMatchRuins(request: APIRequestContext, ruins: TestRuins): Promise<void> {
  const response = await request.post(`${SERVER_URL}${TEST_NEXT_MATCH_RUINS_PATH}`, { data: ruins });
  expect(response.status(), await response.text()).toBe(200);
}

/** Canvas pixels as RGBA rows, read from a real screenshot of the canvas. */
async function canvasPixels(page: Page, points: readonly { x: number; y: number }[], radius: number): Promise<[number, number, number][][]> {
  const png = await page.locator("#game canvas").screenshot();
  return page.evaluate(
    async ({ base64, points, radius }) => {
      const blob = await (await fetch(`data:image/png;base64,${base64}`)).blob();
      const bitmap = await createImageBitmap(blob);
      const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
      const context = canvas.getContext("2d")!;
      context.drawImage(bitmap, 0, 0);
      return points.map(({ x, y }) => {
        const pixels: [number, number, number][] = [];
        for (let dy = -radius; dy <= radius; dy++) {
          for (let dx = -radius; dx <= radius; dx++) {
            const px = x + dx;
            const py = y + dy;
            if (px < 0 || py < 0 || px >= bitmap.width || py >= bitmap.height) continue;
            const [r, g, b] = context.getImageData(px, py, 1, 1).data;
            pixels.push([r!, g!, b!]);
          }
        }
        return pixels;
      });
    },
    { base64: png.toString("base64"), points, radius },
  );
}

function near(pixel: [number, number, number], color: string, tolerance = 24): boolean {
  const want = Number.parseInt(color.slice(1), 16);
  const [r, g, b] = pixel;
  return Math.abs(r - ((want >> 16) & 0xff)) <= tolerance && Math.abs(g - ((want >> 8) & 0xff)) <= tolerance && Math.abs(b - (want & 0xff)) <= tolerance;
}

/**
 * The ids of ships whose colour is actually on the canvas where the scene says it drew them. Reads a real
 * screenshot of the canvas, so it checks rendered pixels rather than scene bookkeeping.
 */
export async function shipsOnCanvas(page: Page): Promise<string[]> {
  const drawn = await drawnShips(page);
  const pixels = await canvasPixels(page, drawn, 0);
  return drawn.filter((ship, index) => near(pixels[index]![0]!, ship.color)).map((ship) => ship.id).sort();
}

/** The camera's scroll, in world pixels. */
export async function camera(page: Page): Promise<{ x: number; y: number }> {
  const [x, y] = ((await page.getByTestId("game").getAttribute("data-camera")) ?? "0,0").split(",").map(Number);
  return { x: x!, y: y! };
}

/**
 * Whether a ship's colour shows anywhere within a few pixels of where a ship at world position (x, y) sub-units would
 * be drawn on this page's canvas.
 */

