      objectives: status === undefined ? undefined : objectivesOf(status),
      caches: [...caches].map(({ x, y, dock }) => ({ x, y, dock })),
    };
  }

  /** The fruit pedestals in sight, as the server last sent them (§9). */
  ingestPedestals(pedestals: Iterable<PedestalSnapshot>): void {
    this.pedestalState = [...pedestals].map(({ island, x, y, full }) => ({ island, x, y, full })).sort((a, b) => a.island - b.island);
  }

  pedestals(): readonly PedestalSnapshot[] {
    return this.pedestalState;
  }

