    this.sectorLines = this.add.graphics().setDepth(0.5);
    this.sectorLabel = this.add
      .text(VIEW_WIDTH / 2, 36, "", { fontFamily: "system-ui, sans-serif", fontSize: `${10 * ART_SCALE}px`, color: cssColor(SECTOR_COLOR) })
      .setOrigin(0.5, 0)
      .setScrollFactor(0)
      .setDepth(9);
    this.createMinimap();''')
rep('''    this.drawEncounters(now);
    this.drawTreasure(now, minimapLeft);''','''    this.drawEncounters(now);
    this.drawTreasure(now, minimapLeft);
    this.drawSectors(now, own === undefined ? undefined : { x: own.x, y: own.y });''')
rep('''  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */''','''  /**
   * §3's sectors: faint 3 × 3 borders on the sea and the name of the sector the ship enters, only while the journal is
   * open or a sector lead is active (`sectorOverlay` decides). It records `data-sectors` ("hidden", or "shown:<sector>")
   * and `data-sector-name` for the browser tests.
   */
  private drawSectors(now: number, own: { x: number; y: number } | undefined): void {
    const journal = this.view.journal();
    const { overlay, entered } = sectorOverlay({ journalOpen: journal.open, entries: journal.entries, own, entered: this.sectorEntered, now });
    this.sectorEntered = entered;
    const report = `${overlay.visible ? `shown:${overlay.sector}` : "hidden"}|${overlay.label}`;
    if (report === this.lastSectorReport) return;
    this.lastSectorReport = report;
    this.drawSectorLines(overlay);
    this.sectorLabel.setText(overlay.label).setVisible(overlay.label !== "");
    this.report.dataset["sectors"] = overlay.visible ? `shown:${overlay.sector}` : "hidden";
    this.report.dataset["sectorName"] = overlay.label;
  }

  private drawSectorLines(overlay: SectorOverlay): void {
    const graphics = this.sectorLines;
    graphics.clear();
    if (!overlay.visible) return;
    graphics.lineStyle(2, SECTOR_COLOR, 0.35);
    for (const tile of overlay.columns) graphics.lineBetween(tile * TILE_PIXELS, 0, tile * TILE_PIXELS, WORLD_HEIGHT);
    for (const tile of overlay.rows) graphics.lineBetween(0, tile * TILE_PIXELS, WORLD_WIDTH, tile * TILE_PIXELS);
  }

  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */''')
