      { n: 1, text: "Sun: Old Stones (island)", reason: "start", status: "stale", replaced: "Replaced by #3: Sun: a carrier seen in Northern Waters 30 s before" },
    ]);
    expect(entryText(entry({ kind: "no-lead", type: "tide" }))).toBe("Tide: no lead");
    expect(journalView(false, undefined, undefined, undefined, islandName)).toMatchObject({ hidden: true, rumors: [], islands: [], collected: "none yet" });
  });

  it("shows the known islands with their ruin as last seen, the collected types and the kit with its §9 description", () => {
    const view = journalView(
      true,
      status({
        knownIslands: [
          { island: 0, unlocked: true, solved: true },
          { island: 1, unlocked: true, solved: false },
          { island: 3, unlocked: false, solved: false },
        ],
        rubbings: ["sun", "moon"],
        kit: "ember",
      }),
      undefined,
      undefined,
      islandName,
